// demo.html is the whole page in one file, generated by scripts/build-demo.mjs. These tests keep
// it from drifting behind the sources and keep its policy as strict as the page's own.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

import { buildDemo, wrapModule } from '../scripts/build-demo.mjs';

const demo = readFileSync(fileURLToPath(new URL('../demo.html', import.meta.url)), 'utf8');

test('the committed demo.html is exactly what the build produces', () => {
  // Any change to a served file changes the demo, so this also says "rebuild the demo".
  assert.ok(demo === buildDemo(), 'demo.html is stale: run node scripts/build-demo.mjs');
});

test('it is self-contained: nothing is loaded from a file next to it', () => {
  assert.equal(/<(script|link|img)[^>]+(src|href)="\.\//.test(demo), false, 'a relative src or href survives');
  assert.equal(/\?v=\d+/.test(demo), false, 'a versioned asset URL survives');
  assert.equal(demo.includes('./fonts/'), false, 'a font is still referenced by path');
  assert.equal(/\bimport\s*\{|^export\s/m.test(demo.replace(/<pre[\s\S]*?<\/pre>/g, '')), false, 'a module statement survives');
});

test('every inline script and style is allowed by its hash, and nothing else is', () => {
  const csp = /http-equiv="Content-Security-Policy"\s+content="([^"]+)"/.exec(demo)[1].replace(/\s+/g, ' ');
  assert.equal(csp.includes("'unsafe-inline'"), false);
  assert.match(csp, /default-src 'none'/);
  assert.match(csp, /font-src data:;/);
  const hash = (s) => `'sha256-${createHash('sha256').update(s, 'utf8').digest('base64')}'`;
  const scripts = [...demo.matchAll(/<script>([\s\S]*?)<\/script>/g)].map((m) => m[1]);
  const styles = [...demo.matchAll(/<style>([\s\S]*?)<\/style>/g)].map((m) => m[1]);
  assert.equal(scripts.length, 2, 'expected the theme bootstrap and the app');
  assert.equal(styles.length, 1);
  const scriptSrc = /script-src ([^;]+);/.exec(csp)[1].trim().split(' ');
  const styleSrc = /style-src ([^;]+);/.exec(csp)[1].trim().split(' ');
  assert.deepEqual(scriptSrc, scripts.map(hash), 'script-src does not match the inline scripts');
  assert.deepEqual(styleSrc, styles.map(hash), 'style-src does not match the inline style');
  assert.equal(/<script[^>]+src=/.test(demo), false, 'an external script would need its own source');
});

test('module scopes keep same-named helpers apart', () => {
  const out = wrapModule('src/x.js', "import { a, b as c } from './plan.js?v=9';\nconst given = 1;\nexport const y = a + c;\nexport function z() {}\n");
  assert.match(out, /const \{ a, b: c \} = __modules\["src\/plan\.js"\];/);
  assert.match(out, /return \{ y, z \};/);
  assert.throws(() => wrapModule('src/x.js', "import { q } from './nowhere.js';"), /does not bundle/);
  assert.throws(() => wrapModule('src/x.js', 'export default 1;'), /cannot bundle/);
});
